package cn.local.golens;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import org.json.*;

public class CoreTest {
 @Test public void captureAndRejectWrongSide(){BoardState b=new BoardState(9);int[] a=new int[81];a[10]=2;a[1]=a[9]=a[11]=1;b.reset(a,1);int[] c=BoardState.play(a,19,1,9);assertNotNull(c);assertEquals(0,c[10]);assertTrue(b.accept(c));assertEquals(2,b.next);int[] wrong=c.clone();wrong[40]=1;assertFalse(b.accept(wrong));assertArrayEquals(c,b.cells);}
 @Test public void suicideAndMissedMoves(){int[] a=new int[81];a[1]=a[9]=2;assertNull(BoardState.play(a,0,1,9));BoardState b=new BoardState(9);int[] multi=new int[81];multi[30]=1;multi[40]=2;assertFalse(b.accept(multi));assertEquals(0,b.moves.size());}
 @Test public void koAndPassHistory()throws Exception{BoardState b=new BoardState(9);int[] s=new int[81];s[10]=2;s[1]=s[9]=s[19]=1;s[2]=s[12]=s[20]=2;b.reset(s,1);int[] cap=BoardState.play(s,11,1,9);assertTrue(b.accept(cap));int[] back=BoardState.play(cap,10,2,9);assertArrayEquals(s,back);assertFalse(b.accept(back));b.pass();assertEquals(1,b.next);JSONObject q=b.query("k",7.5,32,1.2);assertEquals("W",q.getJSONArray("moves").getJSONArray(1).getString(0));assertEquals("pass",q.getJSONArray("moves").getJSONArray(1).getString(1));}
 @Test public void coordinatesAndInitialWhite()throws Exception{BoardState b=new BoardState(19);for(int i=0;i<361;i++)assertEquals(i,b.index(b.coordinate(i)));assertEquals("T1",b.coordinate(360));assertEquals("J19",b.coordinate(8));assertEquals(-2,b.index("I1"));b.reset(new int[361],2);JSONObject q=b.query("w",6.5,20,1);assertEquals("W",q.getString("initialPlayer"));assertEquals(6.5,q.getDouble("komi"),0);}
 @Test public void recoverSingleMissedPassWithoutCorruptingInvalidPosition(){BoardState b=new BoardState(9);int[] white=BoardState.play(b.cells,40,2,9);assertFalse(b.accept(white));assertTrue(b.acceptAfterPass(white));assertEquals(2,b.moves.size());assertEquals(1,b.next);int[] bad=white.clone();bad[0]=1;bad[1]=2;assertFalse(b.acceptAfterPass(bad));assertEquals(2,b.moves.size());assertEquals(1,b.next);}
 @Test public void recoverSeveralUnseenAlternatingMovesButRejectCapturesAndWrongColors(){BoardState b=new BoardState(9);int[] seen=new int[81];seen[0]=1;seen[10]=2;seen[20]=1;seen[30]=2;assertTrue(b.recoverSkippedNoCaptures(seen));assertEquals(1,b.next);assertArrayEquals(seen,b.cells);assertEquals(0,b.moves.size());int[] captured=seen.clone();captured[0]=0;captured[40]=1;captured[50]=2;assertFalse(b.recoverSkippedNoCaptures(captured));assertArrayEquals(seen,b.cells);int[] wrong=seen.clone();wrong[40]=2;wrong[50]=2;assertFalse(b.recoverSkippedNoCaptures(wrong));}
 @Test public void recoverShortGapContainingCaptureOnlyWhenOldGroupIsSurrounded(){BoardState b=new BoardState(9);int[] old=new int[81];old[40]=1;old[31]=old[39]=old[41]=2;b.reset(old,1);int[] s=BoardState.play(old,0,1,9);s=BoardState.play(s,49,2,9);assertEquals(0,s[40]);s=BoardState.play(s,2,1,9);s=BoardState.play(s,3,2,9);assertTrue(b.recoverSkippedWithCaptures(s));assertArrayEquals(s,b.cells);assertEquals(1,b.next);assertEquals(0,b.moves.size());BoardState uncertain=new BoardState(9);uncertain.reset(old,1);int[] bad=s.clone();bad[31]=0;assertFalse(uncertain.recoverSkippedWithCaptures(bad));assertArrayEquals(old,uncertain.cells);}
 static final class Image implements BoardVision.Pixels {int[] rgb=new int[800*1000];public int width(){return 800;}public int height(){return 1000;}public int get(int x,int y){return rgb[y*800+x];}}
 static Image picture(int n,int[] stones){Image image=new Image();Arrays.fill(image.rgb,0xffcfad74);for(int y=0;y<1000;y++)for(int x=0;x<800;x++){if(x>=40&&x<=40+(n-1)*40&&y>=120&&y<=120+(n-1)*40&&((x-40)%40<=1||(y-120)%40<=1))image.rgb[y*800+x]=0xff402d1c;}for(int i=0;i<stones.length;i++)if(stones[i]!=0){int cx=40+i%n*40,cy=120+i/n*40;for(int y=cy-17;y<=cy+17;y++)for(int x=cx-17;x<=cx+17;x++)if((x-cx)*(x-cx)+(y-cy)*(y-cy)<=17*17)image.rgb[y*800+x]=stones[i]==1?0xff181818:0xfff8f8f3;image.rgb[cy*800+cx]=0xffff0000;}return image;}
 @Test public void recognizeThreeSizesAndCalibrationTolerance(){for(int n:new int[]{9,13,19}){int[] stones=new int[n*n];stones[0]=1;stones[n*n-1]=2;stones[3*n+3]=1;stones[5*n+4]=2;Image image=picture(n,stones);for(int offset:new int[]{0,2,-2}){BoardVision.Result r=BoardVision.read(image,40+offset,120+offset,40+(n-1)*40+offset,120+(n-1)*40+offset,n);assertTrue("n="+n+" offset="+offset+" confidence="+r.confidence,r.confidence>=.97);assertArrayEquals(stones,r.cells);}}}
 @Test public void rejectBlankAndObscuredBoard(){Image image=picture(19,new int[361]);Arrays.fill(image.rgb,0xffffffff);assertEquals(0,BoardVision.read(image,40,120,760,840,19).confidence,0);image=picture(19,new int[361]);for(int y=240;y<720;y++)for(int x=200;x<600;x++)image.rgb[y*800+x]=0xff333333;assertTrue(BoardVision.read(image,40,120,760,840,19).confidence<.97);}
 @Test public void onBoardRecommendationDoesNotBecomeAStone(){int[] stones=new int[361];stones[0]=1;stones[40]=2;Image image=picture(19,stones);int[][] marks={{9,9},{11,9},{9,11}};for(int i=0;i<marks.length;i++){int cx=40+marks[i][0]*40,cy=120+marks[i][1]*40,color=i==0?0xff00dc69:0xffff8500;for(int y=cy-20;y<=cy+20;y++)for(int x=cx-20;x<=cx+20;x++){double radius=Math.hypot(x-cx,y-cy);if(radius>16&&radius<19||Math.abs(x-cx)<3&&Math.abs(y-cy)<6)image.rgb[y*800+x]=color;}}BoardVision.Result result=BoardVision.read(image,40,120,760,840,19);assertTrue(result.confidence>=.97);assertArrayEquals(stones,result.cells);}
 @Test public void recognizeShadedWhiteStonesOnBrightWood(){Image image=picture(19,new int[361]);Arrays.fill(image.rgb,0xfff3d57e);for(int y=120;y<=840;y++)for(int x=40;x<=760;x++)if((x-40)%40<=1||(y-120)%40<=1)image.rgb[y*800+x]=0xff402d1c;int[] stones=new int[361];stones[15*19+3]=2;stones[15*19+15]=2;stones[16*19+15]=2;for(int i=0;i<stones.length;i++)if(stones[i]==2){int cx=40+i%19*40,cy=120+i/19*40;for(int y=cy-17;y<=cy+17;y++)for(int x=cx-17;x<=cx+17;x++){double distance=Math.hypot(x-cx,y-cy);if(distance<=17){int shade=(int)Math.round(250-distance*1.5);image.rgb[y*800+x]=0xff000000|(shade<<16)|(shade<<8)|shade;}}}BoardVision.Result result=BoardVision.read(image,40,120,760,840,19);assertTrue(result.confidence>=.97);assertArrayEquals(stones,result.cells);for(int i:new int[]{15*19+3,15*19+15,16*19+15})assertTrue(BoardVision.visuallyOccupied(image,40,120,760,840,19,i));assertFalse(BoardVision.visuallyOccupied(image,40,120,760,840,19,15*19+14));}
 @Test public void visualGuardRejectsBlackAndWhiteButAllowsEmptyIntersections(){int[] stones=new int[361];stones[2*19+4]=1;stones[16*19+15]=2;Image image=picture(19,stones);assertTrue(BoardVision.visuallyOccupied(image,40,120,760,840,19,2*19+4));assertTrue(BoardVision.visuallyOccupied(image,40,120,760,840,19,16*19+15));assertFalse(BoardVision.visuallyOccupied(image,40,120,760,840,19,8*19+8));assertEquals(-1,BoardVision.firstMissedStone(image,40,120,760,840,19,stones));int[] missed=stones.clone();missed[16*19+15]=0;assertEquals(16*19+15,BoardVision.firstMissedStone(image,40,120,760,840,19,missed));}
 @Test public void recognizeStonesWithOppositeColorLastMoveTriangle(){int[] stones=new int[361];stones[8*19+8]=2;stones[10*19+10]=1;Image image=picture(19,stones);for(int at:new int[]{8*19+8,10*19+10}){int cx=40+at%19*40,cy=120+at/19*40,mark=stones[at]==2?0xff101010:0xfff5f5f5;for(int y=cy;y<=cy+17;y++)for(int x=cx;x<=cx+17;x++)if((x-cx)*(x-cx)+(y-cy)*(y-cy)<=17*17)image.rgb[y*800+x]=mark;}BoardVision.Result result=BoardVision.read(image,40,120,760,840,19);assertTrue(result.confidence>=.97);assertArrayEquals(stones,result.cells);}
}
